<?php
$month=trim($_GET['month']??date('Y-m'));if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month)||$month>date('Y-m'))$month=date('Y-m');
$start=$month.'-01';$end=date('Y-m-d',strtotime($start.' +1 month'));$label=date('F Y',strtotime($start));
$previous=date('Y-m',strtotime($start.' -1 month'));$next=date('Y-m',strtotime($start.' +1 month'));
$overview=row('SELECT COUNT(*) orders,COALESCE(SUM(CASE WHEN payment_status="paid" AND status NOT IN ("cancelled","refunded") THEN total ELSE 0 END),0) income FROM orders WHERE created_at>=? AND created_at<?',[$start,$end]);
$sold=(int)scalar('SELECT COALESCE(SUM(oi.quantity),0) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.created_at>=? AND o.created_at<? AND o.status NOT IN ("cancelled","refunded")',[$start,$end]);
$visitors=(int)scalar('SELECT COUNT(DISTINCT visitor_id) FROM analytics_sessions WHERE started_at>=? AND started_at<?',[$start,$end]);
$top=rows('SELECT p.id,p.name,p.image,p.price,p.stock,COALESCE(SUM(CASE WHEN o.status NOT IN ("cancelled","refunded") THEN oi.quantity ELSE 0 END),0) sold FROM products p LEFT JOIN order_items oi ON oi.product_id=p.id LEFT JOIN orders o ON o.id=oi.order_id GROUP BY p.id ORDER BY sold DESC,p.updated_at DESC LIMIT 5');
$orders=rows('SELECT o.id,o.customer_name,o.total,o.currency,o.status,o.created_at,MIN(oi.name) item_name FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id GROUP BY o.id ORDER BY o.created_at DESC LIMIT 6');
$stock=rows('SELECT id,name,image,stock FROM products WHERE status="publish" AND manage_stock=1 AND stock<=5 ORDER BY stock,name LIMIT 6');
$reviews=rows('SELECT r.author_name,r.rating,r.body,r.created_at,p.name product FROM product_reviews r JOIN products p ON p.id=r.product_id ORDER BY r.created_at DESC LIMIT 6');
?>
<link rel="stylesheet" href="<?= url('admin/css/leaflet.css') ?>"><link rel="stylesheet" href="<?= url('admin/css/dashboard.css') ?>">
<div class="tq-dashboard-head"><div><p>Store overview</p><h4><?= h($label) ?></h4></div><div class="tq-month-nav"><a href="?month=<?= $previous ?>" aria-label="Previous month">‹</a><input type="month" id="tq-dashboard-month" value="<?= h($month) ?>" max="<?= date('Y-m') ?>"><a class="<?= $next>date('Y-m')?'disabled':'' ?>" href="?month=<?= $next ?>" aria-label="Next month">›</a></div></div>
<div class="tq-overview-grid">
<?php foreach([['shopping-bag','Products sold',number_format($sold)],['dollar-sign','Total income',money($overview['income'])],['file-text','Orders',number_format((int)$overview['orders'])],['users','Visitors',number_format($visitors)]] as $metric): ?><div class="wg-box tq-overview-card"><div class="tq-overview-icon"><i class="icon-<?= $metric[0] ?>"></i></div><div><span><?= $metric[1] ?></span><strong><?= h($metric[2]) ?></strong><small>During <?= h($label) ?></small></div></div><?php endforeach; ?>
</div>
<div class="report-grid tq-dashboard-lists"><section class="wg-box"><div class="tq-section-head"><div><h5>Top products</h5><span>Best-performing products</span></div><a href="<?= url('admin/manage.php?resource=products') ?>">All products</a></div><div class="tq-list"><?php foreach($top as $p): ?><a href="<?= url('admin/manage.php?resource=products&id='.$p['id'].'&edit=1') ?>"><span class="tq-thumb"><?php if($p['image']): ?><img src="<?= h(url($p['image'])) ?>" alt=""><?php else: ?><i class="icon-image"></i><?php endif; ?></span><span><strong><?= h($p['name']) ?></strong><small><?= h(money($p['price'])) ?> · <?= number_format((float)$p['stock']) ?> in stock</small></span><b><?= number_format((float)$p['sold']) ?> sold</b></a><?php endforeach; ?></div></section>
<section class="wg-box"><div class="tq-section-head"><div><h5>Recent orders</h5><span>Latest customer orders</span></div><a href="<?= url('admin/orders.php') ?>">All orders</a></div><div class="tq-list"><?php foreach($orders as $o): ?><a href="<?= url('admin/orders.php?id='.$o['id']) ?>"><span class="tq-order-icon"><i class="icon-file-text"></i></span><span><strong>#<?= $o['id'] ?> · <?= h($o['item_name']?:'Order') ?></strong><small><?= h($o['customer_name']) ?> · <?= h(date('d M Y',strtotime($o['created_at']))) ?></small></span><b><?= h($o['currency'].' '.number_format($o['total'],2)) ?><em><?= h(ucfirst($o['status'])) ?></em></b></a><?php endforeach; ?></div></section></div>
<div class="report-grid tq-dashboard-lists"><section class="wg-box"><div class="tq-section-head"><div><h5>Latest fulfillment queue</h5><span>Orders awaiting completion</span></div></div><div class="tq-mini-table"><div class="head"><span>Order</span><span>Customer</span><span>Total</span><span>Status</span></div><?php foreach($orders as $o): if(!in_array($o['status'],['pending','confirmed','processing','shipped']))continue; ?><a href="<?= url('admin/orders.php?id='.$o['id']) ?>"><span>#<?= $o['id'] ?></span><span><?= h($o['customer_name']) ?></span><span><?= h($o['currency'].' '.number_format($o['total'],2)) ?></span><span class="status"><?= h(ucfirst($o['status'])) ?></span></a><?php endforeach; ?></div></section>
<section class="wg-box"><div class="tq-section-head"><div><h5>Inventory low stock alerts</h5><span>Products at 5 units or below</span></div></div><div class="tq-mini-table"><div class="head"><span>Product</span><span>ID</span><span>Available</span><span>Alert</span></div><?php foreach($stock as $p): ?><a href="<?= url('admin/manage.php?resource=products&id='.$p['id'].'&edit=1') ?>"><span><?= h($p['name']) ?></span><span>#<?= $p['id'] ?></span><span><?= number_format((float)$p['stock']) ?></span><span class="status <?= $p['stock']<=0?'danger':'' ?>"><?= $p['stock']<=0?'Out of stock':'Low stock' ?></span></a><?php endforeach; ?></div></section></div>
