<div class="tq-traffic-metrics"><div><span>Views for selected day</span><strong id="tq-views">0</strong></div><div><span>Unique visitors</span><strong id="tq-unique">0</strong></div><div><span>Returning visitors</span><strong id="tq-returning">0</strong></div></div>
<div id="tq-month-chart" class="tq-chart"></div><div class="tq-traffic-bottom"><div><h6>Top pages</h6><ul id="tq-top-pages"><li>Loading traffic data…</li></ul></div><div><h6>Device mix</h6><div id="tq-devices" class="tq-device-tags">Loading…</div></div></div>
