<section class="wg-box tq-comments"><div class="tq-section-head"><div><h5>New reviews</h5><span>Latest customer feedback</span></div><a href="<?= url('admin/reviews.php') ?>">All reviews</a></div><?php foreach($reviews as $r): ?><article><strong><?= h($r['author_name']) ?> on <?= h($r['product']) ?></strong><span><?= str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating']) ?></span><p><?= h(mb_strimwidth($r['body'],0,180,'…')) ?></p></article><?php endforeach; ?></section>
